INSERT INTO explanation_groups(slug,title) VALUES ('mustafa-cases','شرح قضايا مصطفى') ON CONFLICT(slug) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,1,'heading','مشروع طبي ضخم أنشأه مصطفى قبل ظهور الشركاء والنزاعات','mustafa-section-1' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','مصطفى مصلح عباسة الشعوبي هو المؤسس الأصلي لمشروع مركز بيكسل الرئيسي التشخيصي، وقد بدأ المشروع بمبادرة شخصية منه لإنشاء مركز طبي متطور بشارع الزبيري بجوار المستشفى الجمهوري بصنعاء.','mustafa-section-1-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','تولى مصطفى إعداد المشروع والبحث عن الموقع والتعاقدات والتجهيزات الإنشائية والكهربائية والفنية، واستعان بالدكتور فهد ثوابه باعتباره متخصصًا في الأشعة ومستشارًا في اختيار الأجهزة الطبية ومواصفاتها.','mustafa-section-1-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','لم يبدأ المشروع نتيجة اجتماع مجموعة شركاء أرادوا إنشاء شركة وإسناد إدارتها إلى مصطفى، بل بدأ كمشروع أسسه مصطفى، ثم أدخل شركاء لتوفير رأس مال إضافي وتقليل حاجته إلى الاقتراض.','mustafa-section-1-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','تأسست الشركة باسم شركة مركز بيكسل الرئيسي التشخيصي – مصطفى وشركاؤه، في صورة شركة توصية بسيطة، وهو شكل قانوني يمنح الشريك المتضامن صلاحيات الإدارة ويجعله يتحمل مسؤوليات أوسع من الشركاء الموصين.','mustafa-section-1-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','أصبح مصطفى الشريك المتضامن والمدير العام وصاحب المسؤولية المباشرة عن إدارة المشروع والتزاماته، بينما دخل بقية الشركاء بصفة شركاء موصين، لهم حقوقهم في الرقابة والاطلاع والحسابات وفق العقد، دون أن تكون لهم صلاحيات الإدارة المقررة للشريك المتضامن.','mustafa-section-1-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','بلغت قيمة رأس المال المتفق عليه 2,300,000 دولار، بينما أثبت التقرير المحاسبي أن التكلفة الفعلية لتأسيس المركز وتجهيزه وصلت إلى نحو 2,672,000 دولار، وهو مبلغ استثماري كبير جرى تحويل معظمه إلى أجهزة طبية وتجهيزات وأصول فعلية.','mustafa-section-1-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','في محضر 7 أغسطس 2021، بلغت حصة مصطفى 759,000 دولار، أي 33% من رأس المال، فضلًا عن المبالغ والالتزامات التي تحملها لتمويل المشروع ومواجهة احتياجاته.','mustafa-section-1-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','المشروع لم يكن مجرد محل تجاري يمكن إيقافه ثم إعادة افتتاحه بسهولة؛ بل منشأة طبية تعتمد على أجهزة مرتفعة القيمة وتحتاج إلى كهرباء مستمرة وتبريد وصيانة وكادر طبي متخصص، وتتأثر بصورة مباشرة بأي توقف طويل.','mustafa-section-1-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','كانت أجهزة الرنين المغناطيسي والأشعة المقطعية تمثل العمود الفقري للمشروع ومصدر الإيرادات الرئيسية التي يفترض أن تغطي الإيجارات والرواتب والكهرباء والصيانة وتسديد الالتزامات والقروض.','mustafa-section-1-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','لذلك فإن أهم ما يجب فهمه منذ البداية هو أن المركز يمتلك أصولًا بملايين الدولارات، لكن قدرته على تسديد الالتزامات تعتمد على تشغيل تلك الأصول وإنتاج الإيرادات، وليس على امتلاك أجهزة مرتفعة القيمة وهي متوقفة.','mustafa-section-1-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-1' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,2,'heading','ناتكو لم تكن مجرد مورد للأجهزة، بل منافسًا يملك مصلحة في السوق نفسه','mustafa-section-2' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','بتاريخ 5 نوفمبر 2020 أبرم المركز عقدًا مع شركة ناتكو الرازي المحدودة بقيمة 1,200,000 دولار لتوريد أجهزة الرنين المغناطيسي والمقطعية والألتراساوند، مع التركيب والتشغيل والتدريب والضمان والصيانة وفق البنود المتفق عليها.','mustafa-section-2-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','كانت ناتكو مرتبطة أيضًا بمركز الرازي الطبي المنافس، وهو ما يجعل العلاقة معها مختلفة عن العلاقة مع مورد أجهزة عادي؛ فهي جهة موردة للمركز، وفي الوقت نفسه ذات مصلحة تجارية في سوق خدمات الأشعة الذي سيدخل إليه بيكسل.','mustafa-section-2-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','امتلكت ناتكو من خلال هذه العلاقة مفاتيح أساسية لتشغيل المشروع: التوريد، والتركيب، والتشغيل، والتدريب، والصيانة، وقطع الغيار، والخبرة الفنية اللازمة للمحافظة على الأجهزة.','mustafa-section-2-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','كان مركز بيكسل، بأجهزته وتجهيزاته وموقعه، مرشحًا لمنافسة مركز الرازي وتقديم خدمات تشخيصية متطورة، ولذلك فإن تعطيله لا يضر بيكسل وحده، وإنما يترك مجالًا أكبر للمنافس القائم.','mustafa-section-2-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','بعد أن دفع مصطفى لناتكو 720,000 دولار من قيمة العقد، طلبت الشركة منه بيع المركز لها، بواسطة مدير المبيعات الذي جاء للتفاوض، وكان المقصود أن يصبح المشروع تابعًا لها أو فرعًا ضمن نشاطها بدل أن يكون منافسًا مستقلًا.','mustafa-section-2-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','رفض مصطفى بيع المركز؛ لأنه لم ينفق تلك الأموال ويتحمل القروض والمخاطر لكي يسلم مشروعه بعد تجهيزه إلى جهة منافسة، وإنما لإنشاء مركز مستقل يحقق الغرض الاستثماري والطبي الذي تأسس من أجله.','mustafa-section-2-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','توجد شهادة يمكن طلبها من مدير المبيعات الذي نقل عرض الشراء، وشاهد آخر على طلب ناتكو شراء المركز، وهي واقعة محورية لأنها سبقت تصاعد الضغوط المالية والتشغيلية.','mustafa-section-2-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','تكتسب محاولة الشراء أهمية خاصة عند مقارنة ما سبقها بما تلاها: فقد انتقلت العلاقة من محاولة امتلاك المركز بالتراضي إلى الضغط بالمبالغ المالية والتشغيل والصيانة والشيكات، وهي قرائن مهمة لفحص الغاية من التصرفات اللاحقة.','mustafa-section-2-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-2' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,3,'heading','بداية إخلال ناتكو بالعقد وتعطيل تشغيل المركز','mustafa-section-3' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','نص عقد ناتكو على سداد 720,000 دولار كدفعة أولى تمثل 60% من قيمة الأجهزة، وعلى تسديد المبلغ المتبقي 480,000 دولار بواسطة اعتماد مستندي من بنك الكريمي وفق الشروط المنصوص عليها في البند الخامس.','mustafa-section-3-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','كانت آلية الاعتماد المستندي ضمانة تعاقدية مهمة للمركز؛ لأنها تحدد طريقة السداد وموعده وتربطه بوصول الأجهزة وفق الاتفاق، بدل ترك المطالبة بكامل المبلغ خاضعة لإرادة ناتكو المنفردة.','mustafa-section-3-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','سدد المركز الدفعة الأولى، لكن حدثت مشكلة في تحويل جزء من الأموال إلى حساب قدمته ناتكو في بنك بالإمارات، وتبين أنه حساب مجمد، مما تسبب في تأخير وصول التحويلات واسترجاعها وتحمل أعباء إضافية.','mustafa-section-3-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','نص العقد على توريد الأجهزة خلال ثلاثة إلى أربعة أشهر من استلام الدفعة الأولى، لكن التوريد تأخر عن المدة المحددة، واستمر المشروع يتحمل أعباء التجهيز والإيجار دون أن يبدأ العمل بالأجهزة كما كان مقررًا.','mustafa-section-3-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','بتاريخ 9 أكتوبر 2021 طالبت ناتكو بمبلغ 480,247 دولارًا نقدًا، وأضافت مطالبة بمبلغ 60,000 دولار تحت مسمى ضريبة مبيعات، بدل الالتزام بآلية السداد عن طريق بنك الكريمي.','mustafa-section-3-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','بتاريخ 25 نوفمبر 2021 أخطرت ناتكو بوصول الأجهزة إلى منفذ عفار بدل ميناء عدن المحدد في العقد، وهو اختلاف مهم عن شروط التوريد وآلية السداد التي جرى الاتفاق عليها.','mustafa-section-3-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','بتاريخ 27 ديسمبر 2021 عادت ناتكو للمطالبة بمبلغ 420,000 دولار، في وقت لم تكن قد استكملت فيه التزامات التركيب والتشغيل.','mustafa-section-3-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','بتاريخ 29 ديسمبر 2021 ظهرت مشكلة الجهد الكهربائي لجهاز الرنين المغناطيسي، رغم أن العقد يلزم ناتكو بإرسال مهندسيها مسبقًا لتحديد المتطلبات الفنية للموقع وإبلاغ المركز بها قبل وصول الأجهزة.','mustafa-section-3-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','بتاريخ 10 يناير 2022 كررت ناتكو المطالبة بنحو 480,249 دولارًا مع مبلغ الضريبة ومبالغ إضافية للتأمين، في استمرار للضغط المالي خارج طريقة الدفع الأصلية.','mustafa-section-3-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','بتاريخ 11 يناير 2022 وجه المركز مذكرة رسمية أوضح فيها أن تركيب وتشغيل الأجهزة لم يكتمل؛ فالرنين لم يكن جاهزًا بالصورة المطلوبة، والمقطعية تحتاج إلى استكمال، والألتراساوند لم يكن قد استوفي التوريد والتجهيز المتفق عليهما.','mustafa-section-3-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','بهذا أصبحت ناتكو تطالب المركز بمدفوعات وتعهدات مالية في الوقت الذي لم يتمكن فيه المركز من الانتفاع الكامل بالأجهزة التي دفع مقابلها مئات الآلاف من الدولارات.','mustafa-section-3-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,12,'paragraph','هنا نشأت الحلقة الأولى لإغراق المشروع ماليًا: تعطل الأجهزة يمنع تحقيق الإيرادات، وانعدام الإيرادات يضعف القدرة على الوفاء بالالتزامات، ثم يُستخدم عدم الوفاء سببًا لزيادة الضغط على المركز وتعطيل التشغيل أكثر.','mustafa-section-3-paragraph-12' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-3' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,4,'heading','إجبار مصطفى على مبالغ وشيكات لم ينص عليها العقد','mustafa-section-4' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','لم يتضمن العقد الأصلي إلزام مصطفى بتحرير مجموعة شيكات شخصية لناتكو بدل الاعتماد المستندي؛ فقد حُددت طريقة الدفع بصورة واضحة في البند الخامس.','mustafa-section-4-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','لكن ناتكو استغلت حاجة المركز الملحة إلى تشغيل الأجهزة، بعد أن تحولت معظم أمواله إلى أصول وتجهيزات لا تحقق الإيرادات، وبدأت تشترط سداد مبالغ وتسليم شيكات لمواصلة تنفيذ التزاماتها.','mustafa-section-4-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','اضطر مصطفى إلى تدبير 240,000 دولار وسدادها في فبراير 2022، رغم أن دفعها بهذه الطريقة لم يكن هو الأسلوب المتفق عليه لتنفيذ الدفعة المتبقية.','mustafa-section-4-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','ترتب على تدبير هذا المبلغ الاقتراض وتحمل أعباء مالية إضافية، وقد ورد في ملف الخسائر أن الفوائد والأعباء المرتبطة بتدبير المبلغ والاقتراض تجاوزت 90,000 دولار.','mustafa-section-4-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','بتاريخ 24 أبريل 2022 أعدت ناتكو محضرًا تضمن ترتيبات جديدة للشيكات والضمانات واستكمال التشغيل، مع أن المحضر لم يوقعه المركز، وإنما كان موقعًا من نائب مدير ناتكو في انتظار موافقته.','mustafa-section-4-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','بتاريخ 17 مايو 2022 أرسلت ناتكو مذكرة تشترط التوقيع على المحضر وتسليم الشيكات لاستكمال إجراءات تشغيل الأجهزة، وهو مستند مهم لإثبات الربط بين تسليم الشيكات وبين أداء التزامات فنية كان العقد قد ألزم ناتكو بها أصلًا.','mustafa-section-4-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','بتاريخ 9 يونيو 2022 ربطت ناتكو استكمال أعمال التشغيل والصيانة بسداد مبلغ يقارب 300,000 دولار، رغم استمرار النواقص الفنية والمطالبات السابقة.','mustafa-section-4-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','بتاريخ 29 يونيو 2022 تسلمت ناتكو شيكات بموجب سند قبض بإجمالي 284,000 دولار، وأصبحت بحوزتها أوراق تجارية يمكن استخدامها في المطالبة والتنفيذ والملاحقة الجزائية.','mustafa-section-4-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','يوجد ضمن ملف ناتكو 15 شيكًا مرتبطة بهذه التعاملات، ويجب فهم الظروف التي حُررت فيها، وعدم فصلها عن عقد التوريد ومذكرات ناتكو التي اشترطت الشيكات مقابل إكمال التشغيل.','mustafa-section-4-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','لم تكن موافقة مصطفى على تحرير الشيكات تعبيرًا عن رغبة حرة في استبدال العقد الأصلي بعلاقة مستقلة تمامًا؛ بل جاءت تحت ضغط الحاجة لإنقاذ مشروع استُثمرت فيه ملايين الدولارات وأصبح مهددًا بالتوقف.','mustafa-section-4-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','وجه الإكراه المالي هنا: أن المورد الذي يلتزم بتركيب الأجهزة وتشغيلها يمتنع عن استكمال ما عليه، ثم يجعل تنفيذ ذلك مشروطًا بتوقيع شيكات وضمانات جديدة، مستغلًا عدم قدرة المشتري على ترك أجهزته مرتفعة القيمة معطلة.','mustafa-section-4-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,12,'paragraph','هذا الإكراه أشد أثرًا في حالة مصطفى؛ لأنه الشريك المتضامن الذي يتحمل مسؤولية الشركة وقروضها، في حين أصبح المورد ممسكًا بالأجهزة من الناحية الفنية وبالشيكات من الناحية المالية والقضائية.','mustafa-section-4-paragraph-12' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-4' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,5,'heading','فرض 60 ألف دولار ضريبة ثم عدم إسقاط الشيكات فعليًا','mustafa-section-5' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','فرضت ناتكو مطالبة إضافية بمبلغ 60,000 دولار تحت مسمى ضريبة مبيعات، وأدخلتها ضمن المطالبات والشيكات، رغم اعتراض المركز على استحقاقها بهذه الصورة.','mustafa-section-5-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-5' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','بتاريخ 29 يونيو 2022 اتفق الطرفان على إحالة النزاع بشأن هذه الضريبة إلى التحكيم.','mustafa-section-5-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-5' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','بتاريخ 4 يوليو 2022 صدر حكم المحكمين لصالح المركز، وقضى بعدم استحقاق ناتكو لمبلغ الـ60,000 دولار على المركز على النحو الذي طالبت به، وإسقاط الشيكات المرتبطة به.','mustafa-section-5-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-5' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','رغم صدور الحكم، لم تقم ناتكو بإعادة الشيكات المقابلة لهذه الضريبة وإسقاطها فعليًا من الأوراق التي تحتفظ بها، واستمرت المطالبات والشيكات مصدرًا للضغط والنزاع.','mustafa-section-5-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-5' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','تكمن خطورة ذلك في أن الحكم لم يقتصر على إثبات خلاف مالي، وإنما كشف أن مطالبة فرضتها ناتكو تحت ضغط تشغيل الأجهزة لم تكن مستحقة وفق حكم التحكيم، ومع ذلك لم تنتهِ آثارها العملية على المركز.','mustafa-section-5-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-5' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','ويجب التمييز عند مراجعة الحساب النهائي بين أصل ثمن الأجهزة، والمبالغ المسددة، والشيكات المحصلة، والشيكات المرتبطة بالضريبة المحكوم بإسقاطها، حتى لا يبقى مبلغ غير مستحق داخل المطالبات والتنفيذ.','mustafa-section-5-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-5' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,6,'heading','ناتكو تستمر في تعطيل الأجهزة حتى بعد استلام الشيكات','mustafa-section-6' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','بعد تسليم الشيكات، وجه المركز بتاريخ 4 يوليو 2022 مذكرة يطالب فيها ناتكو باستكمال التركيب والتشغيل، بعد أن زال العذر المالي الذي كانت تتمسك به.','mustafa-section-6-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','بتاريخ 7 يوليو 2022 تقدم المركز بمذكرة بين فيها استمرار النواقص والأعطال، وطالب ناتكو بتعويض أولي قدره 190,000 دولار عن الأضرار التي لحقت به.','mustafa-section-6-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','بتاريخ 18 يوليو 2022 طالب المركز بإرسال مختصين لفحص الأجهزة، واستكمال التدريب، وتسليم الكتالوجات، والتحقق من المطابقة، وإنجاز التشغيل النهائي.','mustafa-section-6-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','بتاريخ 19 يوليو 2022 أُعدت قائمة بالقطع المستلمة، وهي قائمة جزئية لا تمثل محضر تسليم نهائي مطابقًا للعقد، كما توجد قائمة مستقلة بالنواقص مقارنةً بعرض السعر.','mustafa-section-6-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','يوجد محضر لمهندس شركة فيليبس بتاريخ 18 يونيو 2022 يبين عدم اكتمال جوانب من التركيب والتشغيل؛ وهو دليل فني مستقل في مواجهة الادعاء بأن ناتكو نفذت جميع التزاماتها.','mustafa-section-6-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','نص البند الثاني عشر من العقد على ألا تقل نسبة الهيليوم في جهاز الرنين عند اكتمال التشغيل عن 85%، بينما أثبت التشغيل الأولي نسبة بلغت نحو 56% فقط.','mustafa-section-6-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','نص العقد أيضًا على تدريب خارجي لثلاثة مختصين من المركز، لكن ناتكو استبدلت التدريب الخارجي بترتيبات داخلية دون إكمال ما تم الاتفاق عليه بالصورة الأصلية.','mustafa-section-6-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','استمرت مشكلات الملحقات والأعطال والصيانة، ومنها جهاز المقطعية والحاقن الطبي ونظام التبريد والهيليوم، بينما استمرت ناتكو في توجيه مطالبات مالية إضافية.','mustafa-section-6-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','في يونيو 2022 اضطر المركز إلى رفع دعوى مستعجلة أمام المحكمة التجارية لإلزام ناتكو بتشغيل جهاز المقطعية، إلا أن المحكمة رفضت الطلب المستعجل باعتباره نزاعًا موضوعيًا، فاستمر الضرر دون معالجة فورية.','mustafa-section-6-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','الأهم أن الشيكات أُخذت بحجة استكمال تشغيل الأجهزة، ثم لم يتحقق التشغيل الكامل بعد استلامها. وبذلك حصلت ناتكو على وسيلة ضغط مالي إضافية، بينما بقي المركز يعاني من الضرر التشغيلي نفسه.','mustafa-section-6-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-6' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,7,'heading','كيف أدى إخلال ناتكو إلى الديون والمطالبات اللاحقة؟','mustafa-section-7' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','كان من المفترض أن تبدأ أجهزة المركز في تحقيق إيرادات بعد التوريد والتركيب والتشغيل خلال المدد المتفق عليها، وأن تستخدم تلك الإيرادات لتغطية النفقات الجارية والالتزامات والقروض.','mustafa-section-7-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','لكن تأخر ناتكو في التوريد والتشغيل والصيانة حرم المشروع من الإيرادات الأساسية في فترة التأسيس والأشهر الأولى التي كان يحتاج فيها بشدة إلى السيولة.','mustafa-section-7-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','استمرت على المركز مصروفات شهرية كبيرة تشمل الإيجارات والكهرباء والرواتب؛ وقدرت إحدى الدراسات هذه المصروفات بنحو 13 مليون ريال شهريًا، دون احتساب جميع المصروفات الأخرى.','mustafa-section-7-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','لم يتوقف الضرر عند المبالغ المدفوعة لناتكو؛ بل شمل الأرباح الفائتة، واستهلاك الأجهزة، والتدريب الذي تحمله المركز، والصيانة الذاتية، ومصاريف المحاماة والقروض والفوائد وفقدان العملاء.','mustafa-section-7-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','لم يكن بمقدور مصطفى إيقاف تكاليف الكهرباء اللازمة للمحافظة على الرنين والهيليوم لمجرد تعطل الفحوصات؛ فإيقاف التغذية قد يعرض الجهاز لتلف أكبر من تكاليف تشغيله.','mustafa-section-7-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','اضطر مصطفى إلى تمويل المركز من مصادر إضافية، ومنها القروض والأموال الخاصة ومصادر مالية مرتبطة بصيدلية والده، للمحافظة على المشروع ومحاولة تشغيله وتجنب ضياع الأصول.','mustafa-section-7-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','نشأت نتيجة ذلك التزامات مالية لأطراف آخرين، بعضها تعاملات وقروض وضمانات مستقلة من حيث العقود والأشخاص، لكنها نشأت أو تضخمت في البيئة المالية التي خلّفها تعطل المشروع.','mustafa-section-7-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','وهذه هي العلاقة السببية غير المباشرة المهمة: قد لا تكون ناتكو هي التي أقرضت مصطفى مبلغًا في معاملة أخرى، أو قدمت دعوى ذلك الدائن، لكنها ساهمت بإخلالها في خلق العجز الذي دفعه إلى الاقتراض وأضعف قدرته على الوفاء.','mustafa-section-7-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','ولو أن ناتكو نفذت عقدها وشُغلت الأجهزة في مواعيدها، لكان المركز قادرًا على إنتاج الإيرادات الطبيعية، ولما اضطر مصطفى إلى هذا الحجم من التمويل الاضطراري والشيكات والضمانات، أو لكانت قدرته على السداد أعلى بكثير.','mustafa-section-7-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','ولذلك لا يصح تفسير كل دين ظهر لاحقًا على أنه دليل على سوء الإدارة دون بحث: لماذا احتاج المركز إلى ذلك التمويل؟ وأين ذهبت الأموال؟ وما الأجهزة التي كانت متوقفة؟ وما الإيرادات التي حُرم منها؟','mustafa-section-7-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','كما لا يصح أخذ الحالة المالية المتدهورة التي صنعتها التأخيرات ثم استخدامها حجة لإدانة المدير وحده، مع تجاهل المورد والتمويل المتأخر وتعطيل التشغيل والصيانة.','mustafa-section-7-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-7' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,8,'heading','فهد ثوابه وعلاقته بناتكو والمركز المنافس','mustafa-section-8' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','كان الدكتور فهد ثوابه أحد أهم الأشخاص الذين استعان بهم مصطفى في تأسيس المشروع، باعتباره مستشارًا فنيًا وطبيًا وشريكًا رئيسيًا، وكان له دور في اختيار الأجهزة ومواصفاتها والعلاقة الفنية مع المورد.','mustafa-section-8-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','نشأت بعد ذلك خلافات بسبب تدخله في أعمال الإدارة والجانب الطبي والعلاقات مع الأطباء، ومحاولات فرض خدمات كتابة التقارير الطبية من جهة مرتبطة به وبتكلفة مرتفعة على المركز.','mustafa-section-8-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','ورد في ملف المشروع عقد مقترح لخدمات كتابة التقارير الطبية بمبلغ نحو 8 ملايين ريال شهريًا، مع وجود رقم آخر في بعض الأوراق يبلغ 10 ملايين ريال، ما يجعل العقد والأصل المحاسبي مرجعًا لتحديد الرقم النهائي.','mustafa-section-8-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','حدثت أفعال أضرت بعلاقات المركز مع الأطباء والكادر الطبي، وأضعفت قدرته على بناء شبكة الإحالات الطبية اللازمة لنجاح المشروع، في الفترة التي كان يعاني فيها أصلًا من تعطل الأجهزة.','mustafa-section-8-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','انتقل فهد في مارس 2023 للعمل في مركز الرازي أدفانس المنافس المرتبط بناتكو، رغم مركزه السابق كشريك ومستشار ومسؤول طبي في بيكسل.','mustafa-section-8-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','هذه العلاقة تمثل نقطة اتصال مهمة بين المورد المنافس وبين الخلاف الداخلي للشركاء؛ لأن فهد كان مطلعًا على تفاصيل بيكسل الفنية والمالية وعلاقاته الطبية وصعوباته التشغيلية.','mustafa-section-8-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','لم يعد النزاع هنا مع مورد خارجي وحده؛ بل أصبح هناك تقاطع مصالح بين جهة منافسة تريد الاستفادة من سوق الأشعة وبين شريك داخل الشركة اختلف مع مؤسسها على الإدارة.','mustafa-section-8-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','تعاون عدد من الشركاء مع فهد في مواجهة مصطفى، ومن أبرز الأسماء الواردة في النزاعات فضل المهتدي وأحمد الحظا وغيرهما، وتحولت مطالباتهم إلى مسارات قضائية وإدارية متكررة ضد الشريك المتضامن.','mustafa-section-8-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','أهمية هذا التقاطع أنه يفسر كيف أصبح مركز بيكسل يتعرض لضغوط من خارج الشركة وداخلها في الوقت نفسه، بدل أن يقف شركاؤه جميعًا في مواجهة إخلال المورد والدفاع عن حقوق المشروع.','mustafa-section-8-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-8' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,9,'heading','الشركاء لا يعالجون الأزمة بل يستغلونها للسيطرة على الإدارة','mustafa-section-9' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','أثبت محضر 7 أغسطس 2021 أن بعض الشركاء لم يكونوا قد سددوا حصصهم كاملة، وأن مجموع المبالغ المتبقية حينها بلغ 525,082 دولارًا، وهو مبلغ مؤثر جدًا في مشروع يحتاج سيولة للتأسيس والتشغيل.','mustafa-section-9-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','كان يجب أن تعالج هذه الالتزامات بما يضمن استكمال المشروع وتوفير التمويل، خصوصًا بعد ظهور التكاليف الإضافية وتأخر تشغيل الأجهزة.','mustafa-section-9-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','تحمل مصطفى الجزء الأكبر من مواجهة الالتزامات العاجلة، ولجأ إلى القروض والتمويل الاضطراري، بينما استمر الخلاف مع بعض الشركاء حول الحصص وزيادة رأس المال.','mustafa-section-9-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','بلغت تكلفة المشروع الفعلية نحو 2.672 مليون دولار، بزيادة تقارب 372 ألف دولار على رأس المال المخطط، وهي زيادة ارتبطت بتجهيزات وأصول ومصروفات تأسيس يجب تقييمها من خلال المستندات والتقرير المحاسبي.','mustafa-section-9-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','استعان مصطفى بمحاسب قانوني لمراجعة الحسابات، ثم جرى التعاقد مع مكتب بشير الهيلمة للمحاسبة في أغسطس 2022، وعُرضت الحسابات لمناقشة التكلفة النهائية وتوفير التمويل.','mustafa-section-9-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','بتاريخ 3 نوفمبر 2022 عقد اجتماع لمناقشة تكلفة التأسيس وزيادة رأس المال، وكان الهدف معالجة الاحتياجات المالية للمركز وضمان استمراره.','mustafa-section-9-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','بدلًا من أن تنحصر المناقشة في سداد الالتزامات ومحاسبة ناتكو واستكمال تشغيل الأجهزة، تصاعدت مطالب بعض الشركاء بتغيير الشكل القانوني للشركة ونظام إدارتها.','mustafa-section-9-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','بتاريخ 20 ديسمبر 2022 انعقد اجتماع موثق بتسجيلات كاميرات المراقبة، وجرى فيه طرح تحويل الشركة من توصية بسيطة إلى شركة ذات مسؤولية محدودة، مع التلويح بالتصفية إذا لم تتم الموافقة.','mustafa-section-9-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','رفض مصطفى التغيير؛ لأن عقد الشركة منحه الإدارة مقابل تحمله مركز الشريك المتضامن ومسؤولياته، ولا يجوز التعامل مع رفضه التخلي عن ذلك المركز كما لو كان رفضًا للمحاسبة أو الإصلاح.','mustafa-section-9-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','تكمن خطورة هذا التوقيت في أن المطالبة بنقل الإدارة ظهرت بعد أن أصبح المشروع مجهزًا بأصول ضخمة، وبعد أن تحمل مصطفى مخاطر التأسيس والتمويل، وفي الوقت الذي أضعفته فيه أزمة ناتكو.','mustafa-section-9-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','لذلك فإن تسجيل الاجتماع مهم لإظهار أصل الخلاف: هل كان الهدف معالجة مشكلة الحسابات والتمويل، أم إعادة تشكيل السلطة داخل الشركة وإزاحة الشريك المتضامن عن الإدارة؟','mustafa-section-9-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,12,'paragraph','بدأت تتضح محاولة الاستفادة من أزمة السيولة بوصفها وسيلة ضغط لتغيير عقد الشركة، ثم استخدام رفض مصطفى التغيير لتبرير دعاوى الحراسة والمحاسبة والتصفية.','mustafa-section-9-paragraph-12' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-9' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,10,'heading','تحويل الأضرار التي تسببوا بها إلى اتهامات ضد مصطفى','mustafa-section-10' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','أصبح مصطفى يواجه اتهامات بسوء الإدارة والتسبب بالخسائر والديون، مع أن جانبًا كبيرًا من تلك الخسائر نشأ من تعطل الأجهزة ونقص التمويل واستمرار النفقات قبل التشغيل الكامل.','mustafa-section-10-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','جرى التركيز على النتائج المالية المتأخرة، مثل الديون والعجز وانخفاض الإيرادات، مع إغفال الأسباب التي سبقت ظهورها، وبالأخص إخلال ناتكو وعدم الوفاء الكامل بالتزامات الشركاء في الوقت المحدد.','mustafa-section-10-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','كما جرى تصوير تحمل مصطفى للقروض والشيكات الشخصية بوصفه تصرفًا غير مسؤول، مع أن الغاية من كثير من هذه الالتزامات كانت إنقاذ المشروع وتوفير السيولة ومنع توقفه.','mustafa-section-10-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','استُخدمت مطالبات تقديم الحسابات ومراجعتها مدخلًا للتشكيك في الإدارة، رغم الاستعانة بمحاسبين قانونيين ووجود تقارير ومستندات تبين ما صُرف على الأصول والتجهيزات.','mustafa-section-10-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','كان من الممكن معالجة النزاع وفق عقد الشركة ومن خلال المحاسبة والتحكيم، لكن تكرار الدعاوى والإجراءات أدى إلى تشتيت الإدارة وزيادة الكلفة المالية والقانونية.','mustafa-section-10-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','أصبح مصطفى مطالبًا في الوقت نفسه بتشغيل مركز متعثر، ومتابعة المورد، وتدبير الكهرباء والصيانة والرواتب، وتسديد الدائنين، والرد على الشركاء، وحضور المحاكم والنيابات.','mustafa-section-10-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','كلما ازداد انشغاله بالقضايا قلت قدرته على إنقاذ المركز، وكلما قلت قدرته على تشغيل المركز زادت الديون، ثم استُخدمت الديون لتقديم مزيد من المطالبات والقضايا.','mustafa-section-10-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','وهكذا تحولت الأزمة من إخلالات كان يجب علاجها لحماية المشروع إلى سلسلة من الضغوط المتراكمة التي تصب نتائجها في اتجاه واحد: إضعاف المركز ماليًا وإداريًا وإضعاف موقف مؤسسه.','mustafa-section-10-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-10' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,11,'heading','بداية الانتقال من الخلاف التجاري إلى القضاء والضغط على الحرية','mustafa-section-11' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','في فبراير 2023 رفع بعض الشركاء دعوى حراسة قضائية على الشركة، رغم وجود شرط التحكيم ورغم أن الخلاف يتعلق أساسًا بالحسابات والتمويل والإدارة.','mustafa-section-11-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','بتاريخ 6 مارس 2023 انتهت دعوى الحراسة الأولى بعدم قبولها، وهو حدث مهم لفهم أن محاولة فرض الحراسة بدأت مبكرًا ولم تكن إجراءً فرضته ضرورة ثابتة منذ البداية.','mustafa-section-11-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','طالب مصطفى باللجوء إلى التحكيم وفق عقد التأسيس، وصدر بتاريخ 6 يونيو 2023 حكم بإلزام الشركاء بتنفيذ شرط التحكيم.','mustafa-section-11-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','رغم ذلك استمرت خلافات تشكيل هيئة التحكيم وتسمية المحكمين والمحاسبين، وازدادت الإجراءات التي تعطل الوصول إلى فصل موضوعي في الحسابات والتزامات الشركاء.','mustafa-section-11-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','بدأت كذلك وقائع الضغط والاحتجاز المتعلقة بالتعاملات المالية، ومنها واقعة 26 نوفمبر 2022 التي أُجبر فيها مصطفى أثناء احتجازه بمكتب الرزامي على ضمانة مقدارها أربعة كيلوغرامات من الذهب تخص التزامًا بين محمد السرحي وعدنان المذحجي.','mustafa-section-11-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','تظهر هذه الواقعة المبكرة أن الوسائل المستخدمة في النزاع تجاوزت المطالبات التجارية إلى استعمال الاحتجاز والضغط الشخصي للحصول على التزامات وضمانات مالية.','mustafa-section-11-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','وبذلك انتهت المرحلة الأولى إلى ثلاث نتائج خطيرة: مركز طبي لم يتمكن من التشغيل الطبيعي بسبب إخلال ناتكو، وشركاء دخلوا في صراع على الإدارة بدل إنقاذ المشروع، ومدير تعرض لضغوط مالية وقضائية وشخصية جعلته أقل قدرة على مواجهة الأزمة.','mustafa-section-11-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-11' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,12,'heading','خلاصة المرحلة الأولى: أين تقع المسؤولية الأساسية؟','mustafa-section-12' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','ناتكو هي نقطة البداية في سلسلة الأضرار: لأنها لم تلتزم على الوجه المطلوب بالتوريد والتركيب والتشغيل والتدريب والصيانة، وحولت طريقة السداد إلى مطالبات نقدية وشيكات تحت ضغط تعطيل الأجهزة.','mustafa-section-12-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-12' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','الشركاء الذين تعاونوا مع فهد ثوابه ساهموا في تعميق الأزمة: من خلال الخلاف على رأس المال والتدخل في الإدارة ومحاولة تغيير طبيعة الشركة والتصعيد إلى الحراسة والقضاء، بدل توجيه الجهود لإنقاذ مشروعهم المشترك ومحاسبة المورد.','mustafa-section-12-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-12' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','تلاقت المصلحة التنافسية لناتكو مع مصلحة بعض الشركاء في إزاحة مصطفى عن الإدارة: وهي علاقة يجب فحصها من خلال الوقائع والتوقيت والاتصالات والتصرفات التي جرت بين الأطراف.','mustafa-section-12-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-12' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','لم تكن الأزمة المالية دليلًا تلقائيًا على فشل الإدارة؛ بل كانت النتيجة المتوقعة لتوقف أو ضعف استغلال أصول مكلفة، واستمرار المصروفات والاقتراض وغياب السيولة الكافية.','mustafa-section-12-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-12' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','لو أن ناتكو أوفت بالعقد، والشركاء وفوا بالتزاماتهم وتعاونوا على التشغيل، لما تهيأت ظروف هذا الحجم من التعثر والديون والضغوط. وهذا لا يعني أن كل فعل لاحق قام به شخص آخر كان بأمر مباشر منهم، وإنما يبين أن الأفعال الأولى خلقت الظروف التي استُغلت وتراكمت فيها بقية الأضرار.','mustafa-section-12-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-12' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,13,'heading','تحويل النزاع من مشكلة تجارية إلى وسيلة لاستنزاف مصطفى وإبعاده عن المشروع','mustafa-section-13' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','بعد أن فشلت محاولة ناتكو شراء المركز بالتراضي، وبعد رفض مصطفى تغيير الشكل القانوني للشركة والتنازل عن صلاحيات الإدارة، دخل النزاع مرحلة تصعيد متواصلة شملت دعاوى تجارية، وحراسة قضائية، وشكاوى جزائية، ومطالبات مالية متعددة.','mustafa-section-13-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','لم يعد الأمر مجرد مطالبة مورد بثمن أجهزة، أو اعتراض شركاء على حسابات الشركة؛ بل أصبح مصطفى يواجه ضغوطًا متزامنة من أطراف متعددة، في الوقت الذي كان فيه يحاول تشغيل المركز وإصلاح الأجهزة وتوفير السيولة.','mustafa-section-13-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','تظهر خطورة هذا التصعيد عند النظر إلى اتجاه نتائجه: تجميد الأموال، وتعطيل الإدارة، وإضعاف الإيرادات، وتكاثر الديون، وإشغال المدير بالقضايا، ثم حبسه وتعريض أهم أصول المركز للبيع.','mustafa-section-13-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','استُخدمت أزمة السيولة التي نشأت من إخلال ناتكو وتأخر التمويل ذريعة لاتهام مصطفى بالتقصير، مع أن الأسباب الأصلية للتعثر لم تكن قد عولجت، والأجهزة لم تعمل بكامل طاقتها.','mustafa-section-13-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','دخل عدد من الدائنين وأصحاب المطالبات المالية في النزاعات، وأصبح كل طرف يطالب بمستحقاته دون مراعاة أن توقف الإيرادات وتعدد الحجوزات يزيدان عجز المركز عن سداد الجميع.','mustafa-section-13-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','بعض المطالبات كانت مرتبطة بتعاملات مستقلة عن ناتكو والشركاء من حيث العقود والأشخاص، لكنها ارتبطت بأزمة المركز من حيث سبب الاقتراض، ونقص السيولة، وتعذر السداد، وتعاظم الضرر.','mustafa-section-13-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','الفرق الجوهري هنا: وجود دائن له حق مالي محتمل لا ينفي مسؤولية الأطراف التي تسبب إخلالها في أزمة السيولة. كما أن ثبوت أصل دين لا يبرر التعسف في تنفيذه أو استغلاله لتعطيل مشروع تزيد قيمته بأضعاف كبيرة على مبلغ المطالبة.','mustafa-section-13-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-13' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,14,'heading','استخدام النفوذ والجهات الرسمية لزيادة الضغط على المركز','mustafa-section-14' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','لم تقتصر الإجراءات على المحاكم التجارية، بل امتدت إلى النيابات وأقسام الشرطة وجهات إدارية ورقابية مختلفة، وتكررت الاستدعاءات والبلاغات والحجوزات والإجراءات التي تعطل نشاط المركز وتستنزف إدارة الشركة.','mustafa-section-14-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','برز دور الشريك أحمد الحظا في استعمال علاقاته ونفوذه للتأثير على الإجراءات والقرارات، كما وردت وقائع تتعلق بتحريض فضل المهتدي وتشويه سمعة مصطفى أمام جهات وأشخاص مختلفين.','mustafa-section-14-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','شملت وسائل الضغط تعطيل الحوالات والأموال والادعاء بوجود مخالفات مالية وإدارية، وفتح ملفات أمام جهات متعددة بدل حصر النزاع في الحسابات والتحكيم والحقوق التعاقدية.','mustafa-section-14-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','من الوقائع المهمة إدراج مصطفى في قيود ومتابعات لدى جهات مالية ورقابية، وما ترتب على ذلك من صعوبات في التعامل مع الصرافين وتدبير الأموال اللازمة لتشغيل المركز.','mustafa-section-14-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','أدت الحجوزات المالية إلى مضاعفة العجز، فالمركز يحتاج إلى السيولة لدفع الرواتب والكهرباء والصيانة، بينما حجز الأموال يمنع استخدام الموارد المتاحة للمحافظة على الأصول وإنتاج الإيرادات.','mustafa-section-14-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','امتدت الضغوط أيضًا إلى الموظفين والأطباء والجهات المتعاملة مع المشروع؛ فقد جرى تحريض بعضهم أو التأثير في تعاملاتهم مع المركز، بما أضر بسمعته وثقة المتعاملين معه.','mustafa-section-14-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','تكررت الشكاوى والاستدعاءات الإدارية والقضائية في فترات متقاربة، حتى أصبح الوقت المطلوب للرد عليها ومتابعتها يمثل عبئًا كبيرًا على إدارة المشروع.','mustafa-section-14-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','تكمن دلالة هذا التعدد في أنه لا ينبغي فحص كل إجراء بمعزل عن غيره: يجب مقارنة تواريخ البلاغات والأوامر والإفراجات والحجوزات والأشخاص الذين حركوها لمعرفة ما إذا كان تزامنها ناتجًا عن تنسيق واستغلال نفوذ.','mustafa-section-14-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','توجد في الشكاوى التفصيلية وقائع تخص موظفين وأعضاء نيابة وقضاة ومعاوني تنفيذ، تتعلق بعرقلة الطلبات، وعدم تمكين مصطفى من الملفات، وتأخير الإفراج، والإعلانات غير الصحيحة، وتوجيه إجراءات استثنائية أضرت به.','mustafa-section-14-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','يكتسب التحقيق في النفوذ والتنسيق أهمية خاصة لأن بعض هذه الإجراءات استمر رغم صدور قرارات لصالح مصطفى أو وجود ضمانات أو اعتراضات رسمية، بينما كانت الإجراءات المضرة به تتقدم بصورة أسرع.','mustafa-section-14-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-14' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,15,'heading','تعطيل التحكيم واستعمال الحراسة وسيلة لنزع الإدارة','mustafa-section-15' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','كان عقد تأسيس شركة بيكسل يتضمن شرط التحكيم لحل الخلافات بين الشركاء، وهو الطريق الذي تمسك به مصطفى وطالب بتطبيقه.','mustafa-section-15-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','بعد فشل دعوى الحراسة الأولى في مارس 2023، لم ينتهِ الصراع على الإدارة، بل استمرت المنازعات بشأن تشكيل هيئة التحكيم ومراجعة الحسابات وتسمية المحكمين.','mustafa-section-15-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','اعترض مصطفى على تشكيل هيئة تضم محكمًا من جهته ومحكمين من جهة خصومه، وعلى ما جرى بعد وفاة المحكم عبدالملك الجنداري من إجراءات لتعيين محاسب قبل اكتمال الهيئة بالصورة المتفق عليها.','mustafa-section-15-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','وصل الخلاف على تعيين المحاسب والتعامل معه إلى إصدار أوامر حبس وإحضار بحق مصطفى، بما يعكس انتقال النزاع على الحسابات من مسار مالي وتحكيمي إلى إجراءات تمس حريته الشخصية.','mustafa-section-15-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','توالت دعاوى الحراسة القضائية التي رفعها الشركاء، رغم أن الهدف الأصلي من الحراسة هو المحافظة على الأموال عند توافر شروطها، لا تعطيل المشروع أو نقل الإدارة بالمخالفة لحدود الحكم.','mustafa-section-15-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','في 31 أغسطس 2024 صدر حكم بالحراسة القضائية على مركز بيكسل، ثم صدر حكم استئنافي بتاريخ 19 نوفمبر 2024 يقصر الحراسة على الجانب المالي.','mustafa-section-15-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','رغم ذلك توسعت إجراءات تنفيذ الحراسة إلى التدخل العملي في نشاط المركز وإيراداته وأعماله، ولم تعد آثار الحراسة محصورة في ضبط الحسابات والإيرادات والمصروفات.','mustafa-section-15-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','عُيّن علي عبدالمولى العريقي حارسًا قضائيًا، ورافق إجراءات التنفيذ تدخل أشخاص آخرين في استلام الإيرادات والتعامل مع العاملين والمرضى، مع وجود اعتراضات على حدود التكليف وطريقة التنفيذ.','mustafa-section-15-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','جرى تحصيل أموال من إيرادات المركز دون توفير الاحتياجات التشغيلية الأساسية بالقدر اللازم، ومنها الديزل والكهرباء والصيانة ومستحقات الأطباء والإحالات الطبية.','mustafa-section-15-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','أدت هذه الإجراءات إلى تعطيل العمل والإضرار بالأجهزة وعلاقات المركز المهنية، بدل المحافظة على قدرته على تحقيق الإيرادات التي يمكن من خلالها سداد الدائنين وحماية حقوق الشركاء.','mustafa-section-15-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','النتيجة أن الحراسة تحولت في آثارها من وسيلة لحفظ المشروع إلى عامل إضافي في إضعافه، بما يخدم عمليًا اتجاه التصفية والتخلص من الإدارة القائمة بدل إنقاذ الشركة.','mustafa-section-15-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-15' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,16,'heading','استمرار إخلال ناتكو حتى بعد تفاقم أزمة المركز','mustafa-section-16' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','لم تنتهِ مسؤولية ناتكو عن الصيانة والتشغيل بعد عام 2022؛ فقد استمرت المراسلات والأعطال والمطالبات حتى عام 2024، وما بعده بالنسبة لبعض المشكلات الفنية.','mustafa-section-16-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','بتاريخ 13 يونيو 2024 استمرت الخلافات بشأن الصيانة ونقص الهيليوم والمستحقات، وربطت ناتكو بعض أعمالها الفنية بشروط مالية إضافية.','mustafa-section-16-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','بتاريخ 23 يوليو 2024 استمر الخلاف بشأن صيانة جهاز المقطعية الذي ظل متوقفًا مدة طويلة، رغم أهمية الجهاز في تحقيق الإيرادات اللازمة للمركز.','mustafa-section-16-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','اضطر المركز إلى إصلاح بعض الأعطال على نفقته الخاصة، ومنها أعمال صيانة للمقطعية والرنين والشيلر، إضافة إلى تحمل نفقات التدريب والمراجعات الفنية.','mustafa-section-16-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','بلغت تكاليف بعض الإصلاحات التي سجلها المركز 18,000 دولار للمقطعية في 2022، و21,000 دولار لإصلاحات المقطعية في 2024، فضلًا عن مصروفات صيانة أخرى.','mustafa-section-16-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','لم يكن توقف الأجهزة يسبب خسارة إيرادات الفحوصات فقط؛ بل كان يضعف قدرة المركز على المحافظة على الكادر الطبي والعملاء والأطباء المحولين، ويزيد خطر التعرض لمطالبات الدائنين.','mustafa-section-16-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','وبذلك ظلت ناتكو، بعد سنوات من عقد التوريد، طرفًا مؤثرًا في قدرة المركز على التشغيل، ولم يكن تأثير إخلالاتها حدثًا قديمًا انتهى بمجرد وصول الأجهزة إلى الموقع.','mustafa-section-16-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-16' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,17,'heading','منازعة الحراسة ومحاولات السيطرة على أصول المركز','mustafa-section-17' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','في أواخر 2024 وبداية 2025 تصاعدت إجراءات الحجز والتنفيذ على المركز، وتداخلت مطالبات شركاء ودائنين وموردين مع إجراءات الحراسة القضائية.','mustafa-section-17-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-17' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','في نوفمبر 2024 ظهرت أزمة انقطاع الكهرباء ونقص الوقود اللازم للتشغيل، وما ترتب عليها من تعريض جهاز الرنين المغناطيسي ومكوناته الفنية وغاز الهيليوم لمخاطر كبيرة.','mustafa-section-17-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-17' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','حصلت وقائع تدخل ومحاولة السيطرة على نشاط المركز من أشخاص مرتبطين بمطالبات مالية، ومنها واقعة حضور مدير بنك الأمل ومحمد السرحي إلى المركز في نوفمبر 2024.','mustafa-section-17-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-17' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','في ديسمبر 2024 باشرت إجراءات تنفيذ الحراسة، وقدمت اعتراضات ومنازعات بشأن تجاوز حدود الحكم وآثار التنفيذ على إيرادات المركز وتشغيله.','mustafa-section-17-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-17' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','وفي تلك المرحلة بدأت تتكاثر إجراءات الحجز على موجودات المركز في قضايا مالية متعددة، بدل البحث عن وسائل تحفظ قدرته على العمل وإنتاج الإيرادات.','mustafa-section-17-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-17' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','المشكلة لم تكن مجرد وجود مطالبات مالية: بل كانت في الطريقة التي استُخدمت بها المطالبات والحراسة والحجوزات بصورة أدت إلى تعطيل النشاط الذي يمكن أن يوفر الأموال اللازمة لسداد تلك المطالبات.','mustafa-section-17-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-17' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,18,'heading','أخطر مثال على استهداف أصول المركز — الحجز على الرنين والمقطعية','mustafa-section-18' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','من أخطر الوقائع إجراءات التنفيذ على جهازَي الرنين المغناطيسي والأشعة المقطعية، وهما الجهازان الأساسيان اللذان يقوم عليهما نشاط مركز بيكسل ومصدر إيراداته الرئيسية.','mustafa-section-18-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','جرى توجيه التنفيذ في إطار مطالبات بشيكات تبلغ قيمة أحدها في حدود 45,000 دولار والآخر في حدود 37,000 دولار، وفق المبالغ التي يجري حصرها في ملفات التنفيذ.','mustafa-section-18-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','في المقابل، تبلغ القيمة الاستثمارية التي يقررها ملف المركز للجهازين وتجهيزاتهما ومقومات تشغيلهما نحو مليوني دولار، وهي تختلف عن مجرد القيمة الاسمية لبعض الأجهزة في عقد التوريد الأصلي.','mustafa-section-18-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','الأخطر أن التثمين محل الاعتراض خفض القيمة إلى نحو 200,000 دولار، أي إلى ما يقارب عُشر القيمة الاستثمارية المشار إليها، مما يثير تساؤلات جوهرية عن أسس التقييم والجهة التي أجرته والغرض من قبول هذه القيمة.','mustafa-section-18-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','لا يمكن فهم أثر بيع هذين الجهازين بمقارنة مبلغ الشيك بقيمة الجهاز وحدها؛ بل يجب النظر إلى أنهما يشكلان أساس المشروع، وأن بيعهما يعني فقدان القدرة على تقديم الخدمات التي أُنشئ المركز لأجلها.','mustafa-section-18-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','حتى لو افترضنا صحة المديونية وثبوت استحقاق الشيكين، فإن ذلك لا يبرر تجاهل وسائل تنفيذ أخرى أقل ضررًا، وبالأخص إذا كانت كافية للوفاء بالدين وتحافظ على استمرار النشاط.','mustafa-section-18-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','كان لدى المركز أجهزة ومعدات أخرى متنوعة تقدر قيمتها بنحو 250,000 دولار، وكان من الممكن فحص قابليتها للحجز والبيع ومدى كفايتها لسداد المطالبات دون المساس بالجهازين الرئيسيين.','mustafa-section-18-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','هذا البديل يطرح سؤالًا أساسيًا: لماذا يُتجه إلى الجهازين اللذين يؤدي بيعهما إلى توقف المشروع بصورة شبه نهائية، بينما توجد أصول أقل أهمية للتشغيل ويمكن أن تغطي أصل المطالبات؟','mustafa-section-18-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','بيع الرنين والمقطعية لا يمثل بيع أصلين مستقلين فحسب؛ بل يمثل إنهاء المصدر الرئيسي لإيرادات المركز وتحويل ما تبقى من الأجهزة والتجهيزات والمبنى إلى أصول فقدت جزءًا كبيرًا من جدواها الاقتصادية.','mustafa-section-18-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','ومن هنا تظهر العلاقة بين اختيار الأموال المحجوزة وبين اتجاه تصفية المشروع؛ فإذا كان الهدف مجرد تحصيل الدين، وجب تفسير عدم اللجوء إلى الأموال الأقل ضررًا عند توافر شروط التنفيذ عليها.','mustafa-section-18-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','أما إذا اختيرت الأصول التي يؤدي بيعها إلى القضاء على نشاط المركز رغم عدم التناسب، فإن ذلك يشكل قرينة قوية تستوجب التحقيق في استعمال إجراءات التنفيذ لتحقيق غاية تتجاوز تحصيل مبلغ المطالبة.','mustafa-section-18-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,12,'paragraph','التثمين المنخفض يضاعف الخطورة؛ إذ قد يؤدي إلى انتقال أصول مرتفعة القيمة بأثمان زهيدة، ويحرم الشركة والشركاء والدائنين الآخرين من قيمتها الحقيقية.','mustafa-section-18-paragraph-12' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,13,'paragraph','يجب لذلك جمع أصل تقرير التثمين ومحاضر الحجز وإعلانات المزاد والعروض المقدمة والمستندات المتعلقة بحالة الجهازين، ومقارنتها بقيمة التوريد والاستثمار والقيمة السوقية وقت التنفيذ.','mustafa-section-18-paragraph-13' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,14,'paragraph','في هذه الواقعة يظهر أوضح مثال للفارق بين تحصيل الحقوق وبين تدمير المشروع: يمكن أن يكون أصل الدين مبلغًا محدودًا، لكن طريقة التنفيذ عليه تؤدي إلى ضرر يصيب مشروعًا بملايين الدولارات.','mustafa-section-18-paragraph-14' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-18' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,19,'heading','تنفيذ إجراءات خطيرة بينما مصطفى غائب في السجن','mustafa-section-19' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','لم تحدث هذه الإجراءات في ظروف كان فيها مصطفى حرًا قادرًا على إدارة الشركة وحضور جميع الجلسات والتواصل مع الخبراء والمحامين؛ بل جرى جانب كبير منها أثناء احتجازه.','mustafa-section-19-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','في 25 أبريل 2025 أودع مصطفى حجز النيابة، ثم نُقل إلى السجن الاحتياطي، واستمر احتجازه هناك حتى 31 أغسطس 2026.','mustafa-section-19-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','خلال هذه الفترة كان هو الشريك المتضامن والمدير المخول بإدارة الشركة وتمثيلها، ومع ذلك حُرم عمليًا من إدارة المشروع ومتابعة التزامات الموردين والحفاظ على الإيرادات والأصول بصورة طبيعية.','mustafa-section-19-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','حالت ظروف السجن دون تمكنه من متابعة جميع الملفات والحصول على المستندات في الوقت المناسب، كما صعّبت التواصل المباشر مع المحامين والخبراء والموظفين ومراجعة التقارير.','mustafa-section-19-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','جرت أثناء غيابه إجراءات حجز وتقييم وبيع بالمزاد تمس أهم ممتلكات الشركة، مع وجود اعتراضات جوهرية على صحة بعض الإعلانات وطرق تبليغه وتمكينه من الدفاع.','mustafa-section-19-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','تضمنت بعض محاضر الإعلان إثبات امتناعه عن الاستلام، رغم وجود إفادة من إدارة السجن تنفي واقعة الامتناع المثبتة بعلمها.','mustafa-section-19-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','وظهر في إحدى وقائع الإعلان توقيع وإفادة منسوبان إلى عاقل الحارة، بينما توجد إفادة مختومة منه تنفي صدور التوقيع والإفادة عنه.','mustafa-section-19-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','هذه المحاضر ليست تفاصيل شكلية؛ لأن صحة الإعلان تؤثر على مواعيد الجلسات والطعن وإمكان الاعتراض على الحجز والبيع، وعلى حق مصطفى في معرفة ما يجري في أمواله وشركته.','mustafa-section-19-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','لا يصح أن يستفاد الخصوم من غياب المدير في السجن للمضي في إجراءات مصيرية، ثم يُحمّل هو مسؤولية عدم حضوره أو عدم تقديم اعتراضاته في الوقت المناسب، دون فحص حقيقة الإعلان والتمكين من الدفاع.','mustafa-section-19-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-19' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,20,'heading','الاعتداءات والاختطاف والضغط لإجبار مصطفى على التوقيع','mustafa-section-20' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','إلى جانب الإجراءات القضائية والتجارية، تعرض مصطفى لاعتداءات واحتجاز وضغوط شخصية متكررة، وارتبط بعضها بمطالبات مالية وأشخاص لهم صلات بنزاعات المركز.','mustafa-section-20-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','في واقعة سابقة بتاريخ 26 نوفمبر 2022 تعرض للاحتجاز في مكتب الرزامي، وأُجبر على تحرير ضمانة مقدارها أربعة كيلوغرامات من الذهب تتعلق بضمان محمد خالد السرحي لدى عدنان المذحجي.','mustafa-section-20-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','لم تكن تلك الضمانة نتيجة اقتراض مصطفى أربعة كيلوغرامات من الذهب أو تسلمه المبلغ الذي تمثله، وإنما حُررت أثناء احتجازه وتحت الضغط والإكراه لضمان التزام يخص أشخاصًا آخرين.','mustafa-section-20-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','لهذه الواقعة صلة مهمة بنزاعات المركز والشركاء؛ فقد وردت وقائع تتعلق بتحريض فهد ثوابه وفضل المهتدي لمحمد السرحي على المطالبة بأموال الحصص، وترتب على ذلك نزاع وخسائر مالية لمصطفى.','mustafa-section-20-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','في مارس 2025 تعرض مصطفى للاعتداء بالضرب قرب منزله، ثم اقتحام المنزل وأخذه بالقوة واقتياده إلى مكتب الرزامي، حيث استمر احتجازه قرابة شهر.','mustafa-section-20-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','خلال هذا الاحتجاز جرت ضغوط لإجباره على البصمة والتوقيع على سندات أمانة تتعلق بمبالغ مالية كبيرة، دون أن يكون تحريرها مقابل تسليم أموال أمانة جديدة في تلك اللحظة.','mustafa-section-20-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','ورد ضمن معطيات الاحتجاز تحرير سندات والتزامات بمبالغ تتجاوز 100,000 دولار، كما ورد مبلغ 50 مليون ريال ضمن أوراق تلك المرحلة، ويجب مطابقة كل سند بأصله وتحديد التزامه والمستفيد منه وظروف توقيعه.','mustafa-section-20-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','حضر أشخاص لهم مطالبات ومصالح مرتبطة بنزاع المركز خلال فترة الاحتجاز، وجرى الحديث عن تسوية المطالبات أو بيع المركز وحصصه بثمن منخفض.','mustafa-section-20-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','من الوقائع المهمة حضور أسام الكبسي إلى مكتب الرزامي أثناء الاحتجاز، وما صدر عنه بشأن الإصرار على استمرار حبس مصطفى بدل الاكتفاء بتحصيل المال.','mustafa-section-20-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','انتهى ذلك الاحتجاز بعد تدخلات ووساطات من وزارة الداخلية، ثم توجه مصطفى إلى قسم العلفي لتقديم شكوى بشأن الاعتداء والاحتجاز والإكراه.','mustafa-section-20-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','لم تُستكمل الشكوى على النحو المطلوب، ولم تصل إجراءات التحقيق في تلك الوقائع إلى نتائج تكفل محاسبة المسؤولين عنها وحماية مصطفى من تكرار الاعتداء.','mustafa-section-20-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,12,'paragraph','بعد خروجه تعرض مجددًا لاعتراض مسلح بالقرب من منزله أمام أفراد أسرته، ثم اقتيد إلى جهات أمنية، في استمرار لمسار استعمال القوة وتقييد الحرية.','mustafa-section-20-paragraph-12' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,13,'paragraph','وجه الارتباط المهم بنزاع ناتكو والشركاء أن الاعتداءات لم تقع في فراغ؛ بل جاءت أثناء تصاعد المطالبات المالية ومحاولات إخضاع مصطفى للتنازل أو تحمل ضمانات والتزامات جديدة.','mustafa-section-20-paragraph-13' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,14,'paragraph','ويجب التحقيق في الأشخاص الذين نفذوا الاعتداءات، ومن حرضهم أو وفر لهم الدعم أو استفاد من نتائجها، وفحص الاتصالات والعلاقات بينهم وبين الدائنين والشركاء وممثلي ناتكو، لتحديد دور كل طرف في هذه الأفعال.','mustafa-section-20-paragraph-14' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,15,'paragraph','إن ثبوت أن الأزمة بدأت بإخلال ناتكو لا يكفي وحده لإسناد أمر الاختطاف إليها مباشرة؛ لكن وجود مصالح وعلاقات ومطالبات متزامنة يجعل التحقيق في التحريض والتنسيق ضرورة جوهرية لا يصح تجاهلها.','mustafa-section-20-paragraph-15' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,16,'paragraph','تظهر المظلومية هنا في تحول شخص يحاول المحافظة على مشروعه إلى محتجز تُنتزع منه سندات وضمانات، ثم تُستخدم الأوراق المنتزعة منه في مطالبات قضائية بينما تظل ظروف تحريرها محل اعتراض.','mustafa-section-20-paragraph-16' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-20' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,21,'heading','تحويل الشيكات والمطالبات إلى قضايا جزائية متكررة','mustafa-section-21' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','استُخدمت شيكات ناتكو التي حُررت في سياق التوريد والتشغيل والضغط المالي أساسًا لمطالبات وقضايا جزائية، بدل معالجة أصل الخلاف العقدي وما ترتب عليه من أضرار.','mustafa-section-21-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','جرى توزيع مطالبات ناتكو وشيكاتها على ثلاث قضايا جزائية، مما ترتب عليه تعدد المحبوسيات والضمانات والإجراءات التي يتعين على مصطفى مواجهتها.','mustafa-section-21-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','كان هذا التعدد شديد الأثر؛ إذ يمكن أن يستكمل مصطفى الضمانة أو قرار الإفراج في قضية، ثم يبقى محبوسًا بسبب قضية أخرى تتعلق بالتعامل التجاري نفسه.','mustafa-section-21-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','تأخر تفعيل إحدى محبوسيات ناتكو مدة طويلة، ثم ظهرت عند اقتراب انتهاء موانع الإفراج في القضايا الأخرى، مما أدى إلى استمرار الاحتجاز والحاجة إلى ضمانات جديدة.','mustafa-section-21-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','لم تتوقف القضايا على ناتكو؛ بل تكاثرت شكاوى أشخاص آخرين في فترات متقاربة، ومنهم أشخاص تجمعهم تعاملات أو علاقات مالية وشخصية متصلة بمنازعات المركز.','mustafa-section-21-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','تحولت كثرة البلاغات في حد ذاتها إلى وسيلة للإضرار بسمعة مصطفى وتصويره باعتباره مطلوبًا في قضايا جنائية عديدة، قبل أن يجري الفصل في صحة الاتهامات.','mustafa-section-21-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','النتيجة المهمة أن عددًا كبيرًا من هذه القضايا انتهى بالبراءة أو بألا وجه لإقامة الدعوى أو بالحفظ، رغم ما ترتب على فتحها من قبض وحبس وضمانات وتعطيل للعمل والسمعة.','mustafa-section-21-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','من أمثلة ذلك القضايا المرتبطة بكريمة الشعوبي، ونهى حامد العطاس، وأحمد نعيم، ووداد زيد، ومحمد الثور، ومحسن السقاف، وإياد العطاس، وبنك الأمل، وغيرها.','mustafa-section-21-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','في الحصر السابق وردت نتائج لصالح مصطفى في نحو 11 قضية من مجموعة 15 قضية، ويظل المرجع النهائي للعدد هو سجل الأحكام والقرارات حتى لا تكرر القضية الواحدة عند تعدد أطرافها.','mustafa-section-21-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','هذه النتائج تفرض سؤالًا أساسيًا: كيف تعرض مصطفى لهذا القدر من الحبس والضمانات والتشهير والإجراءات قبل أن تنتهي غالبية تلك القضايا بنتائج تنفي الاتهامات أو تنهي الملاحقة؟','mustafa-section-21-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','لا تكفي نتيجة البراءة وحدها لإثبات التحريض في كل قضية، لكنها عند اقترانها بتكرار البلاغات وتوقيت المحبوسيات وصلات الأطراف تصبح عنصرًا مهمًا لفحص وجود استعمال كيدي أو منظم للإجراءات الجزائية.','mustafa-section-21-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-21' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,22,'heading','استخدام الضمانات والمحبوسيات لاستمرار الحبس','mustafa-section-22' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','تعرض مصطفى للحبس في قضايا متعددة خلال سنوات سابقة، ثم بدأ احتجازه الطويل في أبريل 2025، في ظل تراكم أوامر القبض والمحبوسيات والضمانات.','mustafa-section-22-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','قُدمت ضمانات عديدة للإفراج، لكن رُفض بعضها أو تأخر قبولها أو استكمال إجراءاتها، رغم وجود ممتلكات وضامنين وتقديم متطلبات مختلفة.','mustafa-section-22-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','تضمنت الوقائع فقدان ضمانة سبق استكمال إجراءاتها، وما ترتب عليه من إلزام مصطفى بإعادة إجراءات الضمانة من البداية، وهو ما تسبب في تأخير إضافي للإفراج.','mustafa-section-22-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','كما تأخر إرسال بعض أوامر الإفراج أو تحديث المحبوسيات بعد استكمال الضمانات، وبقيت قيود قديمة تظهر وكأنها موانع قائمة للإفراج.','mustafa-section-22-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','في أغسطس 2026 استُكملت ضمانة متعلقة بإحدى قضايا ناتكو، لكن تزامن ذلك مع تحريك تنفيذ حكم أسام الكبسي، فاستمر احتجاز مصطفى بدل خروجه.','mustafa-section-22-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','هذا التعاقب من أخطر مظاهر المظلومية: كلما اقترب مصطفى من الإفراج ظهرت أو استمرت إجراءات أخرى تحول دون خروجه، وهو ما يستوجب جمع تواريخ جميع أوامر الحبس والإفراج والضمانات في تسلسل واحد.','mustafa-section-22-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','خلال استمرار حبسه كانت أموال المركز وأصوله تتعرض لأضرار متراكمة، بينما تقل قدرته على متابعة القضايا ومنع وقوع الضرر أو الوصول إلى حلول مالية وتشغيلية.','mustafa-section-22-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-22' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,23,'heading','أثر الحبس على تراكم الديون والخسائر — وليس إهمالًا من مصطفى','mustafa-section-23' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','قبل حبس مصطفى كان المركز يعاني أصلًا من إخلالات ناتكو، وتأخر التمويل، والخلافات مع الشركاء، والحراسة، وتعدد الإجراءات، والأعطال الفنية.','mustafa-section-23-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','حبس مصطفى لم يكن نتيجة طبيعية لتوقفه عن إدارة المشروع؛ بل أصبح سببًا جديدًا لتعطيل الإدارة وتعميق الأزمة بعد أن كان يحاول مواجهة الأضرار السابقة.','mustafa-section-23-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','لم يعد قادرًا على الحضور اليومي للمركز أو متابعة الأجهزة والأطباء والموظفين والموردين والصيانة والكهرباء، رغم أنه المدير والشريك المتضامن الذي أسند إليه العقد إدارة الشركة.','mustafa-section-23-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','أدى تغييب المدير إلى ضعف القدرة على اتخاذ القرارات العاجلة، ومتابعة التحصيل وتسوية الديون، واستكمال الصيانة والتعامل مع الأزمات الطارئة.','mustafa-section-23-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','استمرت الإيجارات والكهرباء والرواتب والديون والفوائد والتكاليف القضائية في التراكم، بينما كانت إيرادات المشروع تتناقص أو تتوقف بسبب تعطل التشغيل والإجراءات.','mustafa-section-23-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','لم يكن بمقدور مصطفى من داخل السجن متابعة كل إجراء في المحاكم والنيابات، أو الحصول على الملفات والمستندات وتوقيع المذكرات والتواصل مع المحامين بالصورة التي يستطيعها وهو حر.','mustafa-section-23-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','أدى ذلك إلى صدور إجراءات وأحكام أو تقدم بعض القضايا دون عرض كامل الدفوع والمستندات، مع وجود اعتراضات على الإعلانات وصعوبة الحصول على صور المحاضر والأحكام.','mustafa-section-23-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','لا يجوز اعتبار كل التزام تراكم أثناء حبسه دليلًا على تقصيره، دون النظر إلى أن حرمانه من الحرية كان مانعًا فعليًا من ممارسة الإدارة والدفاع وحماية الأموال.','mustafa-section-23-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','كما لا يصح محاسبته على انخفاض الإيرادات كما لو كان المركز يعمل في ظروف طبيعية، بينما كانت أهم أجهزته تواجه الأعطال والحجوزات، ومديره محبوسًا، والجهات المختلفة تتدخل في شؤونه.','mustafa-section-23-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','كان استمرار حبسه يضاعف خسائر المركز، وخسائر المركز تزيد المطالبات المالية، والمطالبات الجديدة تزيد من صعوبة الإفراج؛ وهكذا تحولت الأزمة إلى دائرة متكررة من الضرر.','mustafa-section-23-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','وتبرز أهمية هذه العلاقة عند تقييم المسؤولية عن التراكمات؛ إذ يجب الفصل بين الالتزام الذي نشأ قبل الحبس، والتأخير الذي حدث خلال الحبس، والخسارة التي تفاقمت بسبب عدم تمكين المدير من ممارسة صلاحياته.','mustafa-section-23-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-23' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,24,'heading','قضية أسام الكبسي واستمرار الحبس بعد التصريح بالاستئناف','mustafa-section-24' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','نشأت معاملة أسام عبدالله حسين الكبسي بتاريخ 13 يناير 2023 بمبلغ 28,000 دولار ارتبط بشراء سيارة ثم تشغيل المبلغ بعائد شهري، وتسلم أسام أرباحًا لمدة 17 شهرًا بإجمالي 11,900 دولار.','mustafa-section-24-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','تحولت المعاملة إلى شكوى خيانة أمانة، رغم أن حقيقة العلاقة وسند المبلغ والمدفوعات اللاحقة من الدفوع الأساسية المؤثرة في تحديد طبيعة النزاع.','mustafa-section-24-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','لم يُمكّن مصطفى في مرحلة التحقيق من مواجهة الاتهام وعرض جميع دفوعه وشهوده بالصورة المطلوبة، كما ظهرت اعتراضات على إجراءات الإعلان وسماع الشهود.','mustafa-section-24-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','صدر الحكم الابتدائي رقم 1067 لسنة 1447هـ بتاريخ 17 فبراير 2026، وصرح مصطفى بالاستئناف في جلسة النطق وهو محبوس.','mustafa-section-24-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','رغم تصريحه بالاستئناف لم يُقيد طعنه ويُرفع إلى محكمة الاستئناف بالصورة المطلوبة، وتأخر تسليمه نسخة الحكم حتى 18 أغسطس 2026.','mustafa-section-24-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','في المقابل بدأت إجراءات تذييل الحكم وتنفيذه قبل تسليمه الفعلي صورة الحكم، ثم صدرت إجراءات مرتبطة بمنع الإفراج والحبس التنفيذي.','mustafa-section-24-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','ورد في ملف التنفيذ خطاب بعدم الإفراج عن مصطفى استنادًا إلى قرار مؤرخ 24 أغسطس 2026، مع اعتراضه على عدم وجود أصل القرار ضمن الملف الذي اطلع عليه.','mustafa-section-24-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','تكمن الخطورة في تعطيل مسار الاستئناف في الوقت الذي تحرك فيه مسار التنفيذ والحبس، رغم أن مصطفى كان محبوسًا ولم يكن قادرًا على متابعة الإجراءات خارج السجن بنفسه.','mustafa-section-24-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','ترتب على ذلك استمراره في الحبس وانتقاله من السجن الاحتياطي إلى حجز المحكمة، بعد أن كان قد أمضى مدة طويلة في مواجهة القضايا والمحبوسيات السابقة.','mustafa-section-24-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-24' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,25,'heading','امتداد الضرر إلى صيدلية الوالد ومنزله','mustafa-section-25' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','صيدلية دار الدواء مملوكة للوالد مصلح حمود عباسة الشعوبي، وهي منشأة مستقلة لها تراخيص ومستندات وأحكام سابقة تدعم ملكيته لها.','mustafa-section-25-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','رغم ذلك امتد التنفيذ في قضية أسام الكبسي إلى الصيدلية باعتبارها من أموال مصطفى، مع أن الوالد ليس المدين في السند التنفيذي.','mustafa-section-25-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','بتاريخ 9 سبتمبر 2026 تعرضت الصيدلية للجرد والحجز والإغلاق، واستمر إغلاقها حتى 30 سبتمبر 2026، رغم تقديم مستندات الملكية ومنازعة الوالد في الإجراءات.','mustafa-section-25-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','ترتب على الإغلاق تعطيل مصدر رزق الوالد، والإضرار بالأدوية والموظفين والموردين والزبائن والسمعة التجارية، فضلًا عن الضغط النفسي والمالي على الأسرة.','mustafa-section-25-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','كان الوالد قد سلم بصيرة منزله في سياق ضمان متعلق بدعوى استرداد الصيدلية، ثم جرى الإصرار على جعلها ضمانًا يتعلق بقضية مصطفى.','mustafa-section-25-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','ارتبطت الموافقة على جعل بصيرة المنزل ضمانًا لمصطفى باستمرار إغلاق الصيدلية وتأجيل الحكم، مما وضع الوالد تحت ضغط شديد للموافقة من أجل إعادة فتح مصدر رزقه.','mustafa-section-25-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','انتهت دعوى الاسترداد بالحكم بانتهاء النزاع بالصلح، دون الفصل في أصل ملكية الصيدلية، مع اعتراض جوهري على الظروف التي تم فيها قبول الضمانة والصلح.','mustafa-section-25-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','بهذا امتدت نتائج الأزمة من مركز بيكسل إلى منشأة مستقلة مملوكة لشخص آخر، ثم إلى منزله وضماناته، في وقت استمر فيه مصطفى محبوسًا وعاجزًا عن متابعة حقوقه بالصورة الطبيعية.','mustafa-section-25-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-25' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,26,'heading','بقية القضايا المالية والتجارية وعلاقتها بالأزمة الأصلية','mustafa-section-26' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','توجد قضايا تجارية ومالية متعددة، منها قضية يحيى الشهاري، وقضايا شركات الأدوية، وقضية عمر العطاس، وبرايم لايف، وقضية عدنان المذحجي، وأوامر أداء ومطالبات أخرى.','mustafa-section-26-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','تختلف الأطراف والمستندات والمبالغ في هذه القضايا، لكن يجمع عددًا منها أنها نشأت أو تصاعدت خلال فترة تعثر المركز وضغوط التمويل والاحتجاز.','mustafa-section-26-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','في قضية يحيى الشهاري توجد مصادقة بتاريخ 28 ديسمبر 2023 على مبلغ 135,620 دولارًا، مع وجود مدفوعات سابقة مجموعها 90,000 دولار، ونزاع حول معنى المصادقة والرصيد الحقيقي والفواتير والتوريد.','mustafa-section-26-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','وفي قضية عدنان المذحجي يرتبط أصل المطالبة بضمانة الأربعة كيلوغرامات من الذهب التي تم تحريرها في ظروف الاحتجاز والإكراه.','mustafa-section-26-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','وتوجد قضايا على صيدلية دار الدواء تتعلق بمديونيات وتعاملات شركات أدوية، مع نزاع بشأن صفة المدين وملكية الصيدلية وصحة توجيه المطالبة إلى مصطفى بدل مالكها.','mustafa-section-26-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','لا يصح إدراج كل هذه القضايا في خانة واحدة من حيث المسؤولية القانونية، لكن يجب عند شرحها بيان الظروف المالية والزمنية المشتركة التي أدت إلى ظهور المطالبات أو تضخمها، ثم فحص دور كل طرف في نشوء كل التزام.','mustafa-section-26-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','الهدف من ربطها بالأزمة الأصلية ليس إنكار جميع المطالبات، بل إظهار أن تعثر السداد وكثرة القضايا كانا من النتائج المتراكمة لتعطيل مشروع كبير وإبعاد مديره عن أعماله.','mustafa-section-26-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-26' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,27,'heading','ما الذي فعله مصطفى في مواجهة هذه الأزمة؟','mustafa-section-27' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','لم يتوقف مصطفى عن المطالبة بحقوق المركز لدى ناتكو؛ بل وجه المذكرات المتكررة لاستكمال التوريد والتركيب والتشغيل والتدريب والصيانة، ورفع دعوى مستعجلة لإلزامها بتشغيل المقطعية.','mustafa-section-27-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','لجأ إلى التحكيم في مطالبة الضريبة البالغة 60,000 دولار، وصدر حكم لصالح المركز بإسقاطها والشيكات المرتبطة بها.','mustafa-section-27-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','استعان بمحاسبين قانونيين لإعداد الحسابات ومراجعة مصروفات التأسيس، ودعا الشركاء إلى الاجتماعات لمعالجة زيادة رأس المال والتمويل.','mustafa-section-27-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','تمسك بعقد تأسيس الشركة وبشرط التحكيم، وطالب بتنفيذ التزامات الشركاء وحماية حق الإدارة وفق الاتفاق.','mustafa-section-27-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','تحمل قروضًا وأعباء مالية شخصية لتغطية احتياجات المركز، وحاول إصلاح الأعطال وتدريب الموظفين وتشغيل الأجهزة ولو بصورة جزئية للمحافظة على النشاط.','mustafa-section-27-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','قدم اعتراضات ومنازعات بشأن الحراسة والحجوزات والتنفيذ وبيع الأجهزة، وحاول المحافظة على الأصول الأساسية للمركز.','mustafa-section-27-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','قدم شكاوى بشأن الاعتداءات والاحتجاز والإكراه، وطالب باستدعاء ملفات أقسام الشرطة والتحقيق في الوقائع والأشخاص الذين نفذوها أو حرضوا عليها.','mustafa-section-27-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','تابع القضايا من داخل السجن رغم صعوبة الوصول إلى المحامين والملفات، وقدم طلبات الحصول على صور الأحكام والمحاضر والطعون والضمانات والإفراج.','mustafa-section-27-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','أعد وقدم 14 شكوى تفصيلية إلى هيئة التفتيش القضائي، تتعلق بالنيابات والقضاة والتنفيذ والحراسة والتحكيم والإعلانات والضمانات والحبس وإغلاق المنشآت والحجز على الأموال.','mustafa-section-27-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','وتكشف هذه الإجراءات أن مصطفى لم يكن متخليًا عن المشروع أو راضيًا عن إهدار أصوله، بل كان يحاول المحافظة عليه ومتابعة حقوقه رغم القيود والضغوط التي واجهها.','mustafa-section-27-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-27' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,28,'heading','محاولة الوصول بالمركز إلى التصفية وبيع الأصول بثمن بخس','mustafa-section-28' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','بدأت ناتكو بطلب شراء المركز عندما كان مشروعًا جديدًا مجهزًا بأجهزة مرتفعة القيمة، ثم تتابعت خلافات السداد والتشغيل والشيكات.','mustafa-section-28-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','بعد ذلك تصاعد الصراع الداخلي مع بعض الشركاء حول تحويل الشركة إلى ذات مسؤولية محدودة، وبرزت مطالبات بالتصفية أو نقل الإدارة.','mustafa-section-28-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','عندما رفض مصطفى تغيير العقد، انتقلت المواجهة إلى الحراسة والقضايا التجارية والجزائية والضغوط المالية والإدارية.','mustafa-section-28-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','ثم جاءت الاعتداءات والاحتجاز والضمانات المنتزعة تحت الإكراه، وأصبح مصطفى ملاحقًا في ملفات متعددة وعاجزًا عن ممارسة إدارة المشروع بحرية.','mustafa-section-28-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','وأثناء حبسه توسعت إجراءات الحجز والتنفيذ والتثمين والبيع، حتى وصلت إلى جهازي الرنين والمقطعية اللذين تعتمد عليهما الشركة في تحقيق أهم إيراداتها.','mustafa-section-28-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','تلاقي هذه الأحداث في نتيجتها يجعل احتمال السعي إلى تصفية المركز والحصول على أصوله بثمن منخفض مسألة مركزية للتحقيق، وبالأخص بعد محاولة ناتكو شراء المركز ورفض مصطفى لذلك.','mustafa-section-28-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','إن قيمة المشروع لا تتمثل في أجهزة منفردة فقط؛ بل في منظومة متكاملة من أجهزة وتجهيزات وموقع وتراخيص وكادر وعلاقات مهنية، ويؤدي تفكيكها إلى خسارة قيمة كبيرة تتجاوز أثمان المنقولات عند بيعها منفصلة.','mustafa-section-28-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','وإذا بيع الجهازان الأساسيان بثمن منخفض، فإن بقية المركز قد يفقد قدرته على العمل، ويصبح من الممكن الاستحواذ على أصوله المتبقية أو تصفيتها بأثمان لا تعكس تكلفة إنشاء المشروع ولا جدواه الأصلية.','mustafa-section-28-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','بهذا تظهر أهمية التحقيق في من طلب الحراسة والتصفية، ومن حرّك التنفيذ، ومن اختار الأجهزة للحجز، ومن أثبت قيمتها، ومن شارك في المزاد أو استفاد من البيع، بدل النظر إلى كل إجراء باعتباره معاملة تنفيذ عادية.','mustafa-section-28-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-28' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,29,'heading','لماذا تمثل هذه الوقائع مظلومية مترابطة وليست مجرد قضايا متفرقة؟','mustafa-section-29' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','لأن البداية كانت مشروعًا طبيًا استثماريًا كبيرًا يملك أصولًا وتجهيزات بملايين الدولارات، ولم تكن البداية عجزًا شخصيًا عن سداد ديون استهلاكية أو امتناعًا عن تنفيذ أحكام.','mustafa-section-29-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','ولأن إخلال ناتكو أدى إلى إضعاف قدرة المركز على التشغيل وإنتاج الإيرادات، وهي القدرة التي يعتمد عليها سداد جميع الالتزامات اللاحقة.','mustafa-section-29-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','ولأن خلاف الشركاء وتصعيدهم جاء في الفترة التي كان المشروع يحتاج فيها إلى معالجة مشكلات المورد والتمويل، فزاد الضغط على الإدارة بدل معالجة الأسباب.','mustafa-section-29-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','ولأن بعض الشركاء اتجهوا إلى الحراسة والتصفية وتغيير الإدارة، في وقت كان فيه مصطفى يتحمل القروض والمخاطر المرتبطة بالشركة بصفته الشريك المتضامن.','mustafa-section-29-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','ولأن المطالبات المالية تحولت إلى قضايا جنائية متعددة أدت إلى سجن مصطفى وتعطيل قدرته على العمل، بينما انتهت مجموعة كبيرة من تلك القضايا بنتائج لصالحه.','mustafa-section-29-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','ولأن الاعتداءات والاختطاف وانتزاع السندات والضمانات تحت الإكراه تزامنت مع تصاعد نزاعات المشروع، بما يستلزم التحقيق في المحرضين والمستفيدين من تلك الأفعال.','mustafa-section-29-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','ولأن إجراءات الحراسة والتنفيذ طالت الأجهزة الأساسية التي يؤدي بيعها إلى إنهاء النشاط، بدل الاكتفاء عند توافر الشروط بأصول أقل تأثيرًا وقادرة على الوفاء بالمطالبات.','mustafa-section-29-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','ولأن مصطفى ظل محبوسًا أثناء إجراءات مصيرية تتعلق بالمشروع، ثم استُخدم تعذر الحضور والمتابعة لتبرير نتائج مضرة بحقه ومصالح الشركة.','mustafa-section-29-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','ولأن الضرر امتد من المركز إلى ممتلكات خاصة بالأسرة وصيدلية الوالد ومنزله، رغم استقلال بعض تلك الأموال عن ذمة مصطفى وعن ديون الشركة.','mustafa-section-29-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','إن تتابع هذه الوقائع وترابط نتائجها يجعل من الضروري فحصها بوصفها منظومة واحدة، مع تحديد مسؤولية كل طرف عن الأفعال المباشرة وعن الأضرار التي تسبب في نشوئها أو تفاقمها.','mustafa-section-29-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-29' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,title,import_key) SELECT id,NULL,30,'heading','الخلاصة النهائية للقضية','mustafa-section-30' FROM explanation_groups WHERE slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,1,'paragraph','بدأت القضية بمحاولة ناتكو شراء مركز بيكسل بعد أن استثمر مصطفى فيه أموالًا طائلة، ثم رفضه بيع المشروع الذي أسسه.','mustafa-section-30-paragraph-1' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,2,'paragraph','تلت ذلك إخلالات ناتكو بالعقد، وفرض مطالبات نقدية وشيكات خارج طريقة الدفع المتفق عليها، وتأخير التوريد والتشغيل والتدريب والصيانة.','mustafa-section-30-paragraph-2' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,3,'paragraph','أدى ذلك إلى حرمان المركز من إيرادات أجهزته الرئيسية، واستمرار المصروفات والقروض والالتزامات، فتدهور وضعه المالي قبل أن تتاح له فرصة تشغيل طبيعية مستقرة.','mustafa-section-30-paragraph-3' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,4,'paragraph','استغل بعض الشركاء هذه الظروف للدخول في صراع على الإدارة وتغيير الشركة والتلويح بالتصفية، بالتزامن مع علاقة فهد ثوابه بالجهة المنافسة.','mustafa-section-30-paragraph-4' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,5,'paragraph','ثم اتسعت الدائرة إلى دعاوى الحراسة والتحكيم والمطالبات والبلاغات الجزائية والاعتداءات والاحتجاز والضمانات المالية المنتزعة بالإكراه.','mustafa-section-30-paragraph-5' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,6,'paragraph','أصبح مصطفى محبوسًا ومغيبًا عن إدارة المشروع، بينما استمرت القضايا والحجوزات والأعطال والخسائر في التراكم، ثم جرت إجراءات تنفيذ طالت أهم الأجهزة التي يقوم عليها نشاط المركز.','mustafa-section-30-paragraph-6' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,7,'paragraph','في المقابل انتهت مجموعة كبيرة من القضايا الجزائية بنتائج لصالح مصطفى، دون أن تعالج هذه النتائج بالضرورة الأضرار التي سبق أن ترتبت على القبض والحبس والتشهير وتعطيل العمل.','mustafa-section-30-paragraph-7' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,8,'paragraph','وصل الأمر في النهاية إلى استمرار الحبس في قضية أسام الكبسي رغم التصريح بالاستئناف، ثم امتداد التنفيذ إلى صيدلية الوالد وإغلاقها والضغط لتقديم بصيرة منزله ضمانًا.','mustafa-section-30-paragraph-8' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,9,'paragraph','المظلومية الأساسية أن الأسباب التي أدت إلى تعثر المركز لم تُعالج، بينما استُخدمت النتائج المالية لذلك التعثر لملاحقة مؤسسه وإبعاده عن الإدارة والحجز على أهم أصول مشروعه.','mustafa-section-30-paragraph-9' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,10,'paragraph','وليست القضية مطالبة بإسقاط حقوق الدائنين أو عدم محاسبة الإدارة عن أي خطأ يثبت عليها، بل مطالبة بكشف الأسباب الحقيقية للأزمة والمسؤولين عنها، وفحص استعمال الإجراءات والحبس والحجوزات، وحماية أصول المركز والحقوق الشخصية للأطراف المتضررة.','mustafa-section-30-paragraph-10' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
INSERT INTO explanation_nodes(group_id,parent_id,position,kind,body,import_key) SELECT g.id,n.id,11,'paragraph','والسؤال الجوهري الذي يجب أن تطرحه هذه القضايا مجتمعة هو: كيف تحوّل مشروع طبي استُثمر فيه نحو 2.67 مليون دولار إلى مشروع مهدد بالتصفية، بينما مؤسسه محبوس، وأهم أجهزته معرضة للبيع بثمن منخفض، والجهات التي تسببت في جانب كبير من أزمة تشغيله وتمويله لم تُحاسب على آثار أفعالها؟','mustafa-section-30-paragraph-11' FROM explanation_groups g JOIN explanation_nodes n ON n.group_id=g.id AND n.import_key='mustafa-section-30' WHERE g.slug='mustafa-cases' ON CONFLICT(import_key) DO NOTHING;
